const recentApprovalForSubject = `-- name: RecentApprovalForSubject :one
select exists(select 1 from proposals where dedupe_key like $1::text || ':%'
  and status in ('approved', 'edited', 'executed') and decided_at >= $2::timestamptz)::bool as recent
`

type RecentApprovalForSubjectParams struct {
	Prefix string    `json:"prefix"`
	Since  time.Time `json:"since"`
}

// A stock step already approved for the same SKU and branch in the last days is being carried out (transfer, PO,
// bundle): the Orchestrator does not propose it again while the stock in Odoo has not moved yet.
func (q *Queries) RecentApprovalForSubject(ctx context.Context, arg RecentApprovalForSubjectParams) (bool, error) {
	row := q.db.QueryRow(ctx, recentApprovalForSubject, arg.Prefix, arg.Since)
	var recent bool
	err := row.Scan(&recent)
	return recent, err
}

const recentInboundWA = `-- name: RecentInboundWA :many
select s.id, s.dealer_id, s.contact_id, s.occurred_at, s.summary, s.payload, c.name as contact_name
from signals s left join contacts c on c.id = s.contact_id
where s.kind = 'wa' and s.dealer_id is not null and s.occurred_at >= $1 and coalesce(s.payload->>'direction','in') = 'in'
order by s.occurred_at
`

type RecentInboundWARow struct {
	ID          uuid.UUID       `json:"id"`
	DealerID    *uuid.UUID      `json:"dealer_id"`
	ContactID   *uuid.UUID      `json:"contact_id"`
	OccurredAt  time.Time       `json:"occurred_at"`
	Summary     *string         `json:"summary"`
	Payload     json.RawMessage `json:"payload"`
	ContactName *string         `json:"contact_name"`
}

func (q *Queries) RecentInboundWA(ctx context.Context, occurredAt time.Time) ([]RecentInboundWARow, error) {
	rows, err := q.db.Query(ctx, recentInboundWA, occurredAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RecentInboundWARow{}
	for rows.Next() {
		var i RecentInboundWARow
		if err := rows.Scan(
			&i.ID,
			&i.DealerID,
			&i.ContactID,
			&i.OccurredAt,
			&i.Summary,
			&i.Payload,
			&i.ContactName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setProposalStatus = `-- name: SetProposalStatus :exec
update proposals set status = $2, executed_at = case when $2 = 'executed' then now() else executed_at end where id = $1
`

type SetProposalStatusParams struct {
	ID     uuid.UUID `json:"id"`
	Status string    `json:"status"`
}

func (q *Queries) SetProposalStatus(ctx context.Context, arg SetProposalStatusParams) error {
	_, err := q.db.Exec(ctx, setProposalStatus, arg.ID, arg.Status)
	return err
}
